/**
 * @param {number[]} nums
 * @param {number} target
 * @param {number} start
 * @return {number}
 */
var getMinDistance = function(nums, target, start) {
    let res = Infinity;

    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === target) {
            res = Math.min(res, Math.abs(i - start));
        }
    }

    return res;
};

/**
 * @param {number[]} nums
 * @param {number} target
 * @param {number} start
 * @return {number}
 */
var getMinDistance = function(nums, target, start) {
    let end = Math.max(start, nums.length - 1 - start);

    for (let i = 0; i <= end; i++) {
        if (nums[start + i] === target || nums[start - i] === target) {
            return i;
        }
    }

    return 0;
};
